param([Parameter(Mandatory=$true)][ValidateSet('baseline','candidate')][string]$BuildRole,[Parameter(Mandatory=$true)][ValidateSet('focused-one','focused-plus-background')][string]$Mode,[Parameter(Mandatory=$true)][ValidatePattern('^[A-Za-z0-9_-]+$')][string]$CellId)
$ErrorActionPreference='Stop'; $stage=if($BuildRole -eq 'baseline'){'C:\ProgramData\274bot-Test\renderer-owner-census-9268890'}else{'C:\ProgramData\274bot-Test\tile-boxed-fb3589a'}
if(-not (Test-Path $stage)){throw 'Role stage missing'}; $vm=Get-VM -Name '274bot-builder'; if([string]$vm.State -ne 'Off' -or [int64]$vm.MemoryAssigned -ne 0){throw 'Builder VM must be off with zero memory'}
if(Get-Process cargo,rustc,panel-play,tui-play,qemu-system-x86_64,vmware-vmx -ErrorAction SilentlyContinue){throw 'Build/frontend/VM overlap'}
$launch=Get-Content 'C:\Users\BotTest\274bot-server-4c95f87\server-launch.json' -Raw|ConvertFrom-Json; $server=Get-CimInstance Win32_Process -Filter "ProcessId=$([int]$launch.pid)"; if(-not $server -or $server.Name -ne 'node.exe'){throw 'Server identity missing'}
$record=[ordered]@{schema='tile-cpu-preflight-v1';cell_id=$CellId;role=$BuildRole;mode=$Mode;count=1;warmup=30;observe=120;teardown=60;backend='cpu_fallback';owner_census=$false;debug=$false;stack_logging=$false;counting=$false;server=@{pid=[int]$server.ProcessId;creation=[string]$server.CreationDate};performanceAcceptance=$false}; $record|ConvertTo-Json -Depth 6|Set-Content (Join-Path 'C:\ProgramData\274bot-Test\renderer-owner-census-9268890' ('preflight-tile-cpu-'+$CellId+'.json')) -Encoding UTF8
